mapper.sql:
d.tenant_id = #{tenantId}
AND (
  c.id IS NOT NULL
  OR d.exception_flag = 1
  OR d.handling_status <> 'RESOLVED'
  OR d.approval_status <> 'NONE'
  OR d.locked_flag = 1
)

  AND d.work_date >= CAST(#{query.startDate} AS DATE)


  AND d.work_date <= CAST(#{query.endDate} AS DATE)


  AND e.workplace_id = #{query.workplaceId}


  AND e.department_id = #{query.departmentId}


  AND (
    e.employee_no LIKE CONCAT('%', #{query.employeeKeyword}, '%')
    OR e.employee_name LIKE CONCAT('%', #{query.employeeKeyword}, '%')
  )




      AND c.id IS NULL
      AND d.exception_flag = 1


      AND c.case_status = #{query.caseStatus}




  AND d.handling_status = #{query.handlingStatus}


  AND c.current_approver_id = 9001

mapper.select:
SELECT id, action_type, operator_id, operator_role, action_comment, created_at
FROM attendance_case_action_log
WHERE tenant_id = #{tenantId}
  AND attendance_case_id = #{caseId}
ORDER BY created_at ASC, id ASC

SELECT id, attendance_daily_id AS attendanceDailyId, case_status AS caseStatus
FROM attendance_case
WHERE tenant_id = #{tenantId}
  AND attendance_daily_id = #{attendanceDailyId}
ORDER BY id DESC
LIMIT 1

SELECT id, attendance_daily_id AS attendanceDailyId, case_status AS caseStatus, current_approver_id AS currentApproverId
FROM attendance_case
WHERE tenant_id = #{tenantId}
  AND id = #{id}
